//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::float::frexp`; the
//! native twin is `benches/native/Bench/FloatFrexp.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::float;
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0.0f64);
    for _ in 0..n {
        x = step(x);
        acc += {
            let (m, e) = float::frexp(
                (-1000000.0 + ((x >> 11) as f64 * (1.0 / 9007199254740992.0)) * 2000000.0),
            );
            m + e as f64
        };
    }
    float::to_bits(acc) as u64
}

fn main() {
    run(|| (), kernel)
}
